/**
 * Token Storage
 *
 * Persists the JWT pair in localStorage so a session survives page reloads
 * and new tabs. Every read and write of the tokens goes through here.
 *
 * Trade-off: anything stored in localStorage is readable by scripts on the
 * page, so keep XSS out (never render user content as raw HTML). For
 * stricter setups, move the refresh token to an httpOnly cookie on the backend.
 *
 * Generated by Blacksmith. You own this file — customize as needed.
 */

export const ACCESS_TOKEN_KEY = 'auth.access'
export const REFRESH_TOKEN_KEY = 'auth.refresh'

/**
 * Bumped when this browser signs out. A token refresh that started earlier
 * must not write a new pair after that, or the session would come back.
 */
let sessionEpoch = 0

export function getSessionEpoch(): number {
  return sessionEpoch
}

export function bumpSessionEpoch(): void {
  sessionEpoch += 1
}

export function hasStoredSession(): boolean {
  return getAccessToken() !== null || getRefreshToken() !== null
}

export function getAccessToken(): string | null {
  return localStorage.getItem(ACCESS_TOKEN_KEY)
}

export function getRefreshToken(): string | null {
  return localStorage.getItem(REFRESH_TOKEN_KEY)
}

export function setTokens(access: string, refresh?: string) {
  localStorage.setItem(ACCESS_TOKEN_KEY, access)
  // Both backends rotate refresh tokens, so keep the newest one
  if (refresh) localStorage.setItem(REFRESH_TOKEN_KEY, refresh)
}

export function clearTokens() {
  localStorage.removeItem(ACCESS_TOKEN_KEY)
  localStorage.removeItem(REFRESH_TOKEN_KEY)
}
